do $$ begin
 if (select count(*) from tcp)<>16 or (select count(*) from skp)<>23 then raise exception 'plan rows'; end if;
 if exists (select 1 from tcp join app.content_item_cells c on c.content_item_version_id=tcp.version_id and c.is_primary and c.superseded_by is null) then raise exception 'topic already present'; end if;
 if exists (select 1 from skp join app.content_item_cells c on c.content_item_version_id=skp.version_id and c.skill_code is not null and c.superseded_by is null) then raise exception 'skill already present'; end if;
end $$;
insert into app.content_item_cells (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,skill_code,is_primary,assignment_status,source,model_run_id,validated_by,validated_at,validation_decision_id)
select version_id,item_id,'ab088009-dc9a-4f93-8824-803e1913505b'::uuid,topic,null,true,'validated','bc_native_topic_tag_2026_10_03:'||src,case src when 'three_family' then 'bc-native-topic-tag-2026-10-03 (gemini-3.8-flash + deepseek-v4-pro + gpt-6.1-sol, 2 samples each; >=5 of 6)' else 'bc-native-topic-tag-2026-10-03 (model vote tied; Claude tiebreak on the item)' end,null,now(),gen_random_uuid() from tcp;
create temporary table ins on commit drop as select skp.*, gen_random_uuid() vd from skp join app.taxonomy_cells tc on tc.taxonomy_source_version='ab088009-dc9a-4f93-8824-803e1913505b' and tc.topic_code=skp.topic and tc.skill_code=skp.skill;
insert into app.content_item_cells (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,skill_code,is_primary,assignment_status,source,model_run_id,validated_by,validated_at,validation_decision_id)
select version_id,item_id,'ab088009-dc9a-4f93-8824-803e1913505b'::uuid,topic,skill,false,status,'skill_bc_4voter_2026_10_03:'||tier,'skills-bc-2026-10-03 (4 voters: claude-opus-5, gpt-5.5, gemini-2.5-pro, gemini-3.8-flash; validated at >=3 of 4)',null,case when status='validated' then now() end,case when status='validated' then vd end from ins;
do $$ declare m text; begin select format('topic cells %s; skill rows %s planned/%s written (%s validated)',(select count(*) from tcp),(select count(*) from skp),(select count(*) from ins),(select count(*) from ins where status='validated')) into m; raise exception 'REHEARSAL %', m; end $$;
rollback;